import React, { useState } from "react";
import axios from "axios";
import { API } from "../config";

function UserLogin({ setUserToken, setView }) {
  const [form, setForm] = useState({});

  const login = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post(`${API}/user/login`, { email: form.email, password: form.password });
      setUserToken(res.data.token);
      localStorage.setItem("uid", res.data.userId);
      alert("User logged in");
      setView("userPanel");
    } catch (err) {
      console.error(err);
      alert(err.response?.data?.message || "Error");
    }
  };

  return (
    <div style={{ padding: 20 }}>
      <h2>User Login</h2>
      <form onSubmit={login}>
        <input placeholder="Email" onChange={(e) => setForm({ ...form, email: e.target.value })} /><br />
        <input type="password" placeholder="Password" onChange={(e) => setForm({ ...form, password: e.target.value })} /><br />
        <button type="submit">Login</button>
      </form>
    </div>
  );
}

export default UserLogin;
